                if (git_smart__ofs_delta_enabled && !git__prefixcmp(ptr, GIT_CAP_OFS_DELTA)) {
                        caps->common = caps->ofs_delta = 1;
                        ptr += strlen(GIT_CAP_OFS_DELTA);
                        continue;
